using DriveOS.Modules.Workforce.Domain.PerformanceReviews; using DriveOS.SharedKernel.Identifiers; using Microsoft.EntityFrameworkCore;
namespace DriveOS.Modules.Workforce.Infrastructure.Persistence.Repositories;
internal sealed class PerformanceReviewRepository(WorkforceDbContext db):IPerformanceReviewRepository{public Task<PerformanceReview?> GetAsync(OrganizationId org,PerformanceReviewId id,bool tracking,CancellationToken ct=default){IQueryable<PerformanceReview> q=db.PerformanceReviews.Include(x=>x.Criteria);if(!tracking)q=q.AsNoTracking();return q.SingleOrDefaultAsync(x=>x.OrganizationId==org&&x.Id==id,ct);}public async Task<IReadOnlyList<PerformanceReview>> ListAsync(OrganizationId org,EmployeeId? employeeId,PerformanceReviewStatus? status,CancellationToken ct=default){var q=db.PerformanceReviews.AsNoTracking().Include(x=>x.Criteria).Where(x=>x.OrganizationId==org);if(employeeId.HasValue)q=q.Where(x=>x.EmployeeId==employeeId.Value);if(status.HasValue)q=q.Where(x=>x.Status==status.Value);return await q.OrderByDescending(x=>x.PeriodTo).ToListAsync(ct);}public Task<bool> HasOverlapAsync(OrganizationId org,EmployeeId employeeId,DateOnly from,DateOnly to,PerformanceReviewId? excluding,CancellationToken ct=default)=>db.PerformanceReviews.AsNoTracking().AnyAsync(x=>x.OrganizationId==org&&x.EmployeeId==employeeId&&x.Status!=PerformanceReviewStatus.Cancelled&&(!excluding.HasValue||x.Id!=excluding.Value)&&x.PeriodFrom<=to&&from<=x.PeriodTo,ct);public void Add(PerformanceReview x)=>db.PerformanceReviews.Add(x);}
